using FluentValidation; using MediatR; using Microsoft.EntityFrameworkCore; using InventorySystem.Application.Interfaces; using InventorySystem.Domain.Entities;
namespace InventorySystem.Application.Features.Stock.Commands;
public record AddStockCommand(int ProductId,int WarehouseId,int Quantity,MovementType Type,string? Reference,string? Notes) : IRequest<int>;
public class AddStockCommandValidator : AbstractValidator<AddStockCommand> { public AddStockCommandValidator(){ RuleFor(x=>x.ProductId).GreaterThan(0); RuleFor(x=>x.WarehouseId).GreaterThan(0); RuleFor(x=>x.Quantity).GreaterThan(0); RuleFor(x=>x.Type).IsInEnum(); } }
public class AddStockCommandHandler(IAppDbContext db) : IRequestHandler<AddStockCommand,int> { public async Task<int> Handle(AddStockCommand r,CancellationToken ct){ var p=await db.Products.FindAsync([r.ProductId],ct)??throw new KeyNotFoundException("Product not found."); _=p; _=await db.Warehouses.FindAsync([r.WarehouseId],ct)??throw new KeyNotFoundException("Warehouse not found."); var item=await db.StockItems.FirstOrDefaultAsync(x=>x.ProductId==r.ProductId&&x.WarehouseId==r.WarehouseId&&!x.IsDeleted,ct); item ??= new StockItem{ProductId=r.ProductId,WarehouseId=r.WarehouseId,Quantity=0}; if(item.Quantity==0&&!db.StockItems.Local.Contains(item)) db.StockItems.Add(item); var delta=r.Type is MovementType.SaleOut or MovementType.TransferOut ? -r.Quantity : r.Quantity; if(item.Quantity+delta<0) throw new InvalidOperationException("Stock cannot be negative."); item.Quantity+=delta; var m=new StockMovement{ProductId=r.ProductId,WarehouseId=r.WarehouseId,Quantity=r.Quantity,Type=r.Type,Reference=r.Reference,Notes=r.Notes}; db.StockMovements.Add(m); await db.SaveChangesAsync(ct); return m.Id; } }
